with metrics as (select id, budget, percent_rank() over w_running as budget_percent_rank, round(budget / sum(budget) over (partition by dept_name, location), 4) as budget_share from departments window w_running as (partition by location order by budget nulls last)) select case when budget >= 4398000 then 'HIGH' else 'LOW' end as budget_tier, case when budget_percent_rank >= 0.89 then 'PREMIUM' else 'STANDARD' end as budget_percent_rank_tier, count(distinct id) as distinct_ids, count(*) as cnt, round(avg(budget_share), 2) as avg_budget_share from metrics group by budget_tier, budget_percent_rank_tier order by distinct_ids desc;
